#[test]
pub(crate) fn resolve_cli_model_name_accepts_verified_native_embedder_aliases() -> Result<(), String>
{
    for alias in [
        ("all-minilm-l6-v2", "minilm"),
        ("minilm", "minilm"),
        ("minilm-384", "minilm"),
        ("fastembed", "minilm"),
        ("MINILM", "minilm"),
        ("multilingual", "multilingual-minilm"),
        ("multilingual-minilm-384", "multilingual-minilm"),
        (
            "paraphrase-multilingual-minilm-l12-v2",
            "multilingual-minilm",
        ),
    ] {
        let resolved = resolve_cli_model_name(alias.0).map_err(|error| error.message)?;
        assert_eq!(resolved, alias.1);
    }
    Ok(())
}

